if __name__ == '__main__':
    for p in pages:
        if p.get('code', {}).get('from_file'):
            source = ROOT / p['code']['from_file']
            if source.exists():
                p['code']['text'] = source.read_text(encoding='utf-8')
    data = {'title':'Your Verilog to Tiny Tapeout', 'subtitle':'A short practical guide using an existing eight-bit shift register',
            'date':'11 October 2026', 'pages':pages}
    (ROOT / 'lesson.json').write_text(json.dumps(data, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
    print(f'Authored {len(pages)} pages from new lesson content.')
